// DFCND1: flip-flop on the rising edge of cp, IQ <= d, clear when ~cdn; q = IQ; qn = ~IQ
`celldefine
module DFCND1 (cdn, cp, d, q, qn
`ifdef USE_POWER_PINS
  , vdd, vss
`endif
);
  input cdn;
  input cp;
  input d;
  output q;
  output qn;
`ifdef USE_POWER_PINS
  inout vdd;
  inout vss;
`endif
  reg IQ;
  always @(posedge cp or negedge cdn) begin
    if (~cdn) IQ <= 1'b0;
    else IQ <= d;
  end
  assign q = IQ;
  assign qn = ~IQ;
endmodule
`endcelldefine

