// DFCSNQD1: flip-flop on the rising edge of cp, IQ <= d, clear when ~cdn, preset when ~sdn; q = IQ
`celldefine
module DFCSNQD1 (cdn, cp, d, q, sdn
`ifdef USE_POWER_PINS
  , vdd, vss
`endif
);
  input cdn;
  input cp;
  input d;
  output q;
  input sdn;
`ifdef USE_POWER_PINS
  inout vdd;
  inout vss;
`endif
  reg IQ;
  always @(posedge cp or negedge cdn or negedge sdn) begin
    if (~cdn) IQ <= 1'b0;
    else if (~sdn) IQ <= 1'b1;
    else IQ <= d;
  end
`ifndef SYNTHESIS
  always @(posedge cdn) if (~sdn) IQ <= 1'b1;
  always @(posedge sdn) if (~cdn) IQ <= 1'b0;
`endif
  assign q = IQ;
endmodule
`endcelldefine

