// SDFQND0: flip-flop on the rising edge of cp, IQ <= (d & ~se) | (se & si); qn = ~IQ
`celldefine
module SDFQND0 (cp, d, qn, se, si
`ifdef USE_POWER_PINS
  , vdd, vss
`endif
);
  input cp;
  input d;
  output qn;
  input se;
  input si;
`ifdef USE_POWER_PINS
  inout vdd;
  inout vss;
`endif
  reg IQ;
  always @(posedge cp) begin
    IQ <= (d & ~se) | (se & si);
  end
  assign qn = ~IQ;
endmodule
`endcelldefine

